    content: `**पं.भास्कर भटांची ग्रंथ संपदा :-**

आचार्य श्रीनागदेव देवदर्शनास गेल्यावर बाईदेव व्यास हे दुसरे आचार्य झाले.बाईदेव व्यास यांनी तीन वर्ष आचार्यपद सांभाळले. त्यानंतर भास्कर भटांकडे आचार्यपद आले. या काळातही काही ग्रंथांचे लेखन पं.भास्कर भटांनी केले. एकंदरीत पुढील ग्रंथ संपदांचे कर्तृत्व त्यांच्याकडे जाते.

१) निर्वचन स्तोत्र
२) पूजावसराचे सत्तावीस श्लोक
३) प्रास्ताविक ३९ श्लोक
४) नरविलाप स्तोत्र
५) गद्यचाली सात-पाच श्लोक
६) श्रियाष्टक
७) अवतार घटक
८) विरहाष्टक
९) शिशुपाल वध
१०) जयाष्टक
११) ऋद्धुपूरीचे ४० श्लोक
१२) उद्धवगीता

अशी ग्रंथसंपदा त्यांच्या नावावर मोडते.

पं.भास्कर भटांचे १.नरविलाप स्तोत्र २.पूजावसराचे २७ श्लोक ३. चाळीसा स्तोत्र आणि ४. श्रियाष्टक हे चार ग्रंथ संस्कृत व इतर ६ ग्रंथ मराठीत आहेत. इतर-२ मोकळे श्लोक त्यांनी रचले आहेत संस्कृत प्रमाणे मराठी भाषेवर त्यांचे प्रभुत्व आहे हे दिसून येते. ते शीघ्र कवी होते.श्रीनागदेवाचार्य देवदर्शनास गेल्यावर शिशुपाल वधा नंतर उद्धव गीता एकादश स्कंधावर लिहिलेली आहे.उद्धव गीता ग्रंथ आणि ज्ञानेश्वरी ज्याने वाचली असेल त्याला हा ग्रंथ तोडीस तोड असा झाला आहे. संत ज्ञानेश्वरांच्या पहिल्या ओळीत बसण्याचा मान आमच्या पंडित भास्कर भटांना आहे असे म्हणणे वावगे ठरू नये. आचार्य श्रीनागदेवांच्या देवदर्शन गमना नंतर बाईदेव व्यास पंथाचे आचार्य झाले. तीन वर्षानंतर आचार्यपदाचा मान भास्कर भटांकडे आला. पण ते मार्गातील परिवार/आश्रमस्थ परिवार घेऊन एका जागी कुठे ही अधिक काळ स्थिरावलेले दिसत नाहीत.अटन क्रमाने ते कोकण प्रांतात गेले. सोबत दंते गोपाळबास, नाती नागाईसा आदि मान्यवर मंडळींच्या सोबत अटन विजन भिक्षा भोजन तसेच शास्त्र चर्चा अधून मधून घडत असे. पं.भास्कर भटावर सर्वजण अत्यंत प्रेम व आदर करतांना दिसून येतात. सर्वांशी मिळून मिसळून वागण्याचा त्यांचा स्वभाव आहे. असेच एकदा पं.भास्कर भट्ट अटनात दंते गोपाळबास यांच्या सोबत कोकण प्रांतात अटन करू लागले, या अटन क्रमात पं.भास्कर भट्ट अशक्त झाले. माझ्यामुळे तुमचा अटन क्रमात व विजनात अडथळा येऊ नये म्हणून फाकणी केली अर्थात विभागणी केली. ते एकटेच अटन- विजन करू लागले. विजन करतांना नाम स्मरणात लिळांच्या चिंतनात ते भान हरपत असत. भिक्षेची वेळ निघून जाई. त्यामुळे दोन-दोन दिवस उपवास घडत असे, या कारणाने ते अधिकच अशक्त होऊ लागले. दंते गोपाळबास त्यापासून दूर अटन करायचे पण अधून-मधून एक दोन दिवसात ते पं.भास्कर भटांची भेट घेऊन आरोग्य विषयक काळजी घेत असत.

एक दिवशी ते ज्वराने तापले. विजनात, ईश्वर स्मरणात ,लिळांच्या चिंतनात विरह करू लागले. इतके की अनुतापाने ते अत्यंत अशक्त- दुर्बल झाले, अरण्यात एका झाडाखाली ते बेशुद्ध अवस्थेत पडलेले दंते गोपाळबासांना दिसले, तेव्हा दंते गोपाळबासांनी त्यांना पाण्याचा बोळा ओला करून त्यांच्या मुखात पाण्याचे थेंब टाकले. काही काळाने ते शुध्दीवर आले तेव्हा, दंते गोपाळबासांना म्हणाले, “मी देवा कडे जात होतो तुम्ही का थांबविले? असे का केले ? ” यावर दंते गोपाळबास म्हणाले, “ तुम्ही बहुतासि रक्षण ”, यावेळी आपला देहान्त व्हावा अशी सर्वज्ञांची इच्छा नाही, अजून परमार्गाला / ईश्वर मार्गाला तुमची आवश्यकता आहे. म्हणूनच ईश्वर कृपेने हा योग आला आहे. यानंतर बराच काळ गेल्यावर दंते गोपाळबास चंदनवंदनकडे अटनक्रमे निघून गेले व तिकडेच त्यांचे देहावसान झाले.

भट्टांना त्यांनी मृत्यूपूर्वी लिहून ठेवलेल्या चिठ्ठीत छिन्नस्थळी ची माहिती मिळाली त्यानुसार पं.भास्कर भट्टांनी शोध घेतला अन् ती मिळाली. याच कालखंडात नाती नागाईसांचे सत्रसिंगाकडे देहावसान झाल्याचे समजताच आचार्य भास्कर भट्ट तिकडे जातात. तिथे ही नागाईसा आपल्याजवळची छिन्नस्थळीचा विशेष कुठे आहे हे तिने लिहिले होते. त्यानुसार ती मिळाला.दुःखी व जड अंतकरणाने पं.भास्कर भट्ट तिकडून अ.नगर भागातील कडा–आष्टी भागात येतात. जवळच रामदरा आहे. डोंगराळ भाग पाहून अटन विजन करतात. जीवनातील अखेरचे दिवस याच प्रांतात घालविले. याच काल खंडात शिशुपाल वध हा ग्रंथ केला. हा ग्रंथ उत्कृष्ट तर आहे, परंतु “ निवृत्ता जोगा नोहे ”असा ज्येष्ठ बंधूचा अभिप्राय आल्यावर भागवतातील एकादश स्कंधावर उद्धव गीता हा परम उत्तम भक्तांची लक्षणे सांगणारा ग्रंथ लिहिला. हा ग्रंथ वाचणाऱ्या वाचकाला उद्धवाचे आणि श्रीकृष्ण भगवंतांचे संवाद वाचून मेघदूत लिहिणाऱ्या कालिदासाची आठवण आल्या शिवाय राहत नाही. महाकवि कालिदास हे रामटेक चा आधार घेतात.आणि पं.भास्कर भट्ट रामदरा जवळ करतात. फरक एवढाच कालिदास आपल्या प्रियतमेच्या आठवणीत अश्रू ढाळतो आणि आमचे पं.भास्कर भट्ट ईश्वर वियोगाचे दुःखाने विरह भावतात. कालिदासाची करंगुळी पकडण्याचे धाडस आमच्या पं.भास्कर भट्ट यांच्यात आहे. अगदी त्याच धर्तीवर हा ‘नरविलाप’ ग्रंथ आहे. पं.भास्कर भट्ट जेव्हा उद्धवांचे वर्णन करतात. तेव्हा वाचकांच्या डोळ्यातून अश्रू धारा लागतात. असाच काहीसा अनुभव नरविलाप स्तोत्र काव्य वाचतांना वाचकाला येतो.`
